// Decoding Garmin's native .FIT format.
//
// The fixture is generated by Garmin's OWN encoder (@garmin/fitsdk) — see
// scripts/make-fit-fixture.mjs — so this tests the decoder against the real format
// rather than against my idea of it. Every constant in _parseFIT was read out of
// that SDK: field numbers from Profile.messages[18], sizes from
// Fit.BaseTypeDefinitions, the epoch from utils.js. Guessing a field number means
// silently importing wrong distances, which is worse than not importing at all.
import pw from '/opt/node22/lib/node_modules/playwright/index.js';
const { chromium } = pw;
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const APP = pathToFileURL(new URL('../index.html', import.meta.url).pathname).href;
const FIT = [...readFileSync(new URL('./fixtures/garmin-run.fit', import.meta.url))];
const results=[]; const check=(n,c,d='')=>{results.push({n,c:!!c});console.log(`${c?'PASS':'FAIL'}  ${n}${d?' — '+d:''}`);};
const browser=await chromium.launch({executablePath:'/opt/pw-browsers/chromium-1194/chrome-linux/chrome'});
const page=await (await browser.newContext({viewport:{width:393,height:852}})).newPage();
const errs=[]; page.on('pageerror',e=>errs.push(String(e)));
await page.goto(APP,{waitUntil:'load'});
await page.evaluate(()=>{localStorage.setItem('ht-onboarded','true');sessionStorage.setItem('mc-shown','1');});

const act = await page.evaluate((bytes)=>_parseFIT(new Uint8Array(bytes).buffer,'12345678.fit'), FIT);

check('A real Garmin .FIT decodes without error', act && !act.error, act && act.error);
// Values the encoder actually wrote — these are exact, not approximate.
check('Distance is exact (12345.67 m)', act.distance===12345.67, String(act.distance));
check('It returns the SAME shape as the GPX/TCX parsers', 
  !!(act.gid && act.start_date_local && act.sport_type && act.distance!=null),
  Object.keys(act).join(','));
check('Duration uses timer time, not elapsed', act.elapsed_time===3211, String(act.elapsed_time));
check('Average HR survives', act.average_heartrate===154, String(act.average_heartrate));
check('Average speed is unscaled correctly', Math.abs(act.average_speed-3.846)<0.001, String(act.average_speed));
check('Sport is decoded from the enum', act.fitSport==='running', act.fitSport);
check('Start time uses the FIT epoch, not the Unix one',
  act.start_date_local==='2026-09-05T06:30:00.000Z', act.start_date_local);
check('It is tagged as coming from a .FIT', act.source==='FIT', act.source);

// ── Rejection: a wrong file must fail loudly, not import garbage ────────────
const bad = await page.evaluate(()=>({
  tooSmall: _parseFIT(new Uint8Array([1,2,3]).buffer,'x.fit'),
  notFit:   _parseFIT(new TextEncoder().encode('<?xml version="1.0"?><gpx></gpx>').buffer,'x.fit'),
  badHeader:_parseFIT(new Uint8Array(40).buffer,'x.fit'),
}));
check('A file too small is rejected', !!bad.tooSmall.error, bad.tooSmall.error);
check('An XML file named .fit is rejected, not silently parsed',
  !!bad.notFit.error && /signature|header/i.test(bad.notFit.error), bad.notFit.error);
check('A zeroed buffer is rejected', !!bad.badHeader.error, bad.badHeader.error);
check('...and every rejection says why in plain words',
  [bad.tooSmall,bad.notFit,bad.badHeader].every(x=>x.error && x.error.length>15));

// ── Truncation must not produce a plausible-looking wrong number ────────────
check('A truncated .FIT does not invent a distance', await page.evaluate((bytes)=>{
  const half=new Uint8Array(bytes.slice(0, Math.floor(bytes.length/2))).buffer;
  const r=_parseFIT(half,'t.fit');
  return !!r.error || r.distance===12345.67; }, FIT));

// ── It reaches the real import path ────────────────────────────────────────
check('The import UI offers FIT alongside GPX and TCX', await page.evaluate(()=>{
  renderMoreSettings?.();
  return /FIT\/GPX\/TCX/.test(document.body.innerHTML); }));
check('The importer reads .fit as binary, never as text', await page.evaluate(()=>{
  const src=importActivityFiles.toString();
  return /arrayBuffer\(\)/.test(src) && /_parseFIT/.test(src); }));
check('A decoded .FIT converts into a loggable session', await page.evaluate((bytes)=>{
  const a=_parseFIT(new Uint8Array(bytes).buffer,'12345678.fit');
  const r=_activityToSession(a,{allowOutOfRange:true});
  return !!(r && r.session && parseFloat(r.session.dist)>12 && parseFloat(r.session.dist)<13); }, FIT),
  await page.evaluate((bytes)=>{ const a=_parseFIT(new Uint8Array(bytes).buffer,'x.fit');
    const r=_activityToSession(a,{allowOutOfRange:true}); return JSON.stringify(r&&r.session||r); }, FIT));

check('No real JS errors', errs.filter(e=>!/Failed to load resource|ERR_|net::|Chart/.test(e)).length===0,
  errs.slice(0,3).join(' | '));
await browser.close();
const fails=results.filter(r=>!r.c);
console.log(`\n${results.length-fails.length}/${results.length} checks passed`);
process.exit(fails.length?1:0);
